//
// Pure logic of the Apple Magic Trackpad settings page (Qt Core only, no
// widgets/QML), a port of app/mac_trackpad_settings/core.py:
//
// - slider positions <-> macOS speeds (nearest position, ties to the lower one)
// - paths: config dir, environment for mac-trackpad-accel, where the tool is
// - accel.conf: parse the "# generated by mac_curves.py: ..." header so the
//   values the page doesn't show (gains, resolution, ...) are passed through
// - mac-trackpad-accel: build the `set` options
// - daemon.json: set one boolean key, keep everything else, write atomically

#pragma once

#include <QByteArray>
#include <QJsonObject>
#include <QList>
#include <QMap>
#include <QProcessEnvironment>
#include <QString>
#include <QStringList>

#include <optional>

class TrackpadLogic
{
public:
    // ------------------------------------------------------------ settings

    static QString momentumKey(); // "momentum"
    static QString dragKey(); // "threeFingerDrag"
    static constexpr bool momentumDefault = true;
    static constexpr bool dragDefault = false;

    // The tracking speeds macOS has curves for, one slider position each.
    static const QList<double> &pointerPositions();
    // The scroll speeds of the macOS slider.
    static const QList<double> &scrollPositions();

    // Slider position whose value is closest to value; ties go to the lower
    // position.
    static int nearestPosition(double value, const QList<double> &positions);
    // The speed of a slider position (clamped to the valid range).
    static double positionValue(int position, const QList<double> &positions);

    // Short decimal text: 1.5, 0.3125, 160, 15.875 (as core.format_number).
    static QString formatNumber(double v);

    // ------------------------------------------------------------ paths

    // $MAC_TRACKPAD_CONFIG_DIR, else $XDG_CONFIG_HOME/mac-trackpad, else
    // $HOME/.config/mac-trackpad.
    static QString configDir(const QProcessEnvironment &env);

    struct AccelEnv {
        QProcessEnvironment env;
        QString error; // empty when fine
    };
    // Environment for mac-trackpad-accel so it writes accel.conf into
    // configDir(): with $MAC_TRACKPAD_CONFIG_DIR (which must end in
    // /mac-trackpad) XDG_CONFIG_HOME is pointed at its parent.
    static AccelEnv accelEnv(const QProcessEnvironment &env);

    // $MAC_TRACKPAD_ACCEL, else ~/.local/bin/mac-trackpad-accel if it is a
    // file, else the one on $PATH, else ~/.local/bin/mac-trackpad-accel.
    static QString findAccelTool(const QProcessEnvironment &env);

    // ------------------------------------------------------------ accel.conf

    // Keys: pointerSetting pointerGain scrollSetting scrollGain
    //       kwinScrollFactor res step
    using Values = QMap<QString, double>;

    // Curve values from accel.conf's leading comment lines (plus step from
    // motion_step=). Only the fields found are returned.
    static Values parseHeader(const QString &text);

    struct AccelConf {
        bool exists = false;
        Values values; // parseHeader() of the file when it exists
        QString error; // set when it exists but can't be read
    };
    static AccelConf readAccelConf(const QString &path);

    // Defaults as in mac_curves.py's argparse.
    static Values accelDefaults();
    // The header values found (conf, nullopt for a missing file), the rest
    // from defaults.
    static Values accelValues(const std::optional<Values> &conf, const Values &defaults);
    // mac_curves.py options for `mac-trackpad-accel set` (without "set"),
    // every value explicit, in a fixed order.
    static QStringList buildSetArgs(const Values &values);

    // ------------------------------------------------------------ daemon.json

    struct DaemonConfig {
        QJsonObject data; // {} for a missing or empty file
        QString error; // set when unreadable or malformed
    };
    static DaemonConfig readDaemonJson(const QString &path);

    // A switch from a daemon config (def where missing or not a boolean).
    static bool switchEnabled(const QJsonObject &data, const QString &key, bool def);

    // text with only key set to value: the value of an existing key is
    // replaced in place (all other bytes untouched), a missing key is
    // appended. nullopt + error for malformed JSON or a non-object.
    static std::optional<QByteArray> setBoolKey(const QByteArray &text, const QString &key, bool value, QString *error);

    // Re-read path, set only key, write it atomically keeping the file mode
    // (0644 for a new file; the directory is created). A malformed file is
    // never overwritten. Returns false + error on failure.
    static bool writeBoolKey(const QString &path, const QString &key, bool value, QString *error);
};
